  async function startCloud(){const client=window.meadowSupabase;if(!client)return;cloudClient=client;let {data:{session},error}=await client.auth.getSession();if(!session&&!error){({data:{session},error}=await client.auth.signInAnonymously())}if(error||!session){cloudClient=null;console.warn('Meadow & Market online sign-in unavailable',error?.message);return}cloudUser=session.user;const profile={user_id:cloudUser.id,friend_code:state.friendCode,display_name:'Meadow Farmer',updated_at:new Date().toISOString()};let profileResult=await client.from('meadow_market_profiles').upsert(profile,{onConflict:'user_id'});if(profileResult.error){console.warn('Meadow & Market profile sync failed',profileResult.error.message);cloudUser=null;return}const {data:remote,error:readError}=await client.from('meadow_market_saves').select('save_data,updated_at').eq('user_id',cloudUser.id).maybeSingle();if(readError)console.warn('Meadow & Market cloud load failed',readError.message);if(remote?.save_data){const localGrant=state.testGoldGranted&&!remote.save_data.testGoldGranted;if(Number(remote.save_data.seen||0)>Number(state.seen||0)){const merged={...remote.save_data};if(localGrant){merged.coins=(Number(merged.coins)||0)+8000;merged.testGoldGranted=true}localStorage.setItem(SAVE_KEY,JSON.stringify(merged));location.reload();return}}scheduleCloudSave();client.channel('meadow_market_save_'+cloudUser.id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'meadow_market_saves',filter:'user_id=eq.'+cloudUser.id},payload=>{if(payload.new?.save_data&&Number(payload.new.save_data.seen)>Number(state.seen)){localStorage.setItem(SAVE_KEY,JSON.stringify(payload.new.save_data));location.reload()}}).subscribe();window.dispatchEvent(new CustomEvent('meadow-cloud-ready'))}
