  function renderBuildTray(){const tray=$('#build-tray');if(!tray)return;tray.hidden=state.mode!=='build';$('#build-tray-items').innerHTML=catalog.map(i=>`<button class="tray-item ${state.placing===i.id?'chosen':''}" data-place="${i.id}" title="${i.name}"><span>${i.kind==='animal'?'<img class="tray-animal" src="assets/generated/'+(i.id==='chicken'?'hen':i.id)+'.png" alt="">':i.emoji}</span><b>${i.name}</b><small>${state.level<(i.unlock||1)?'🔒 Level '+i.unlock:i.price?'🪙 '+i.price:'Free'}</small></button>`).join('');$$('[data-place]').forEach(b=>{let start=null,dragging=false,suppressClick=false,pointerId=null;b.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};pointerId=e.pointerId;dragging=false;suppressClick=false});b.addEventListener('pointermove',e=>{if(!start||pointerId!==e.pointerId||dragging)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>10){if(e.pointerType==='touch'&&Math.abs(dx)>Math.abs(dy)*1.15){start=null;return}dragging=true;try{b.setPointerCapture(e.pointerId)}catch{}}});b.addEventListener('pointerup',e=>{const wasDragging=dragging;start=null;pointerId=null;dragging=false;suppressClick=wasDragging;if(!wasDragging)return;const type=b.dataset.place,cell=isoCellFromPoint(e.clientX,e.clientY);state.moving=null;state.selected=null;mode('build');state.placing=type;placeAt(cell.x,cell.y)});b.addEventListener('pointercancel',()=>{start=null;pointerId=null;dragging=false});b.onclick=()=>{if(suppressClick){suppressClick=false;return}state.moving=null;state.selected=null;state.placing=b.dataset.place;$('#tray-help').textContent='Tap or drag '+catalog.find(x=>x.id===state.placing).name+' onto a clear tile.';$('#farm-land').classList.add('building-mode');gridRender();renderBuildTray()}})}
