  function plant(p){if(!p.plantedAt&&!(p.stage||0)){p.stage=1;save();render();guideEvent('till');notify('Soil tilled and ready for seeds 🌾');return}if(!p.plantedAt){showCropChooser(p);return}const m=maps.find(x=>x.id===state.active),choices=(m?.crops||['carrot']).filter(k=>k!=='apple'||state.active==='orchard');const available=choices.find(k=>(current().inventory[k]||0)>0);if(available){p.crop=available;current().inventory[available]--;p.plantedAt=Date.now();p.stage=1;save();render();guideEvent('plant');notify('Planted '+crops[available].name.toLowerCase()+' seeds 🌱');return}const k=choices.find(x=>crops[x].seed===0)||choices[0];if(state.coins<crops[k].seed){notify('Sell a few goods to collect more coins');return}state.coins-=crops[k].seed;p.crop=k;p.plantedAt=Date.now();p.stage=1;save();render();guideEvent('plant');notify('Planted '+crops[k].name.toLowerCase()+' seeds 🌱')}
