  function openBuild(filter){const list=$('#build-list');const visible=catalog.filter(i=>!filter||i.kind===filter);list.innerHTML=visible.map(i=>`<button class="build-option" data-type="${i.id}"><span class="item-icon">${i.emoji}</span><span class="task-main"><strong>${i.name}</strong><small>${i.description}</small></span><span class="price">${i.price?'🪙 '+i.price:'Free'}</span></button>`).join('');$$('.build-option',list).forEach(b=>b.onclick=()=>buyPlace(b.dataset.type));$('#build-dialog').showModal()}
