  function expand(){const f=current(),level=expansionLevel(f);if(level>=3){notify('You have opened every meadow expansion 🌿');return}const price=[320,540,820][level],newRows=7+level,newTiles=Array.from({length:32},(_,i)=>i-10).reduce((n,y)=>n+Array.from({length:36},(_,i)=>i-10).filter(x=>meadowCell(x,y)&&!tileUnlocked(x,y,f)&&(level===2||y<8+level)).length,0);openModal(`<div class="sheet-head"><div><small class="eyebrow">ROOM TO GROW · ${level+1} OF 3</small><h2>Open the next meadow</h2></div><button class="close-button" data-close="modal-dialog">×</button></div><p class="sheet-copy">The isometric grid stays in place while a new band of sunny land opens on this farm.</p><div class="welcome-card"><h3>Meadow expansion · 🪙 ${price}</h3><p>Unlocks ${newTiles} grass-only matching grid tiles in row ${newRows+1}, right here on ${maps.find(m=>m.id===state.active)?.name||'your farm'}.</p></div><div class="stats-row"><div class="stat-card"><span>Land open now</span><b>${7+level} rows</b></div><div class="stat-card"><span>New tiles</span><b>${newTiles}</b></div><div class="stat-card"><span>Expansions left</span><b>${2-level}</b></div></div><button class="primary-button full-button" id="expand-confirm" ${state.coins>=price?'':'disabled'}>Open this meadow · 🪙 ${price}</button>`);$('#expand-confirm').onclick=()=>{if(state.coins<price)return;state.coins-=price;f.expansionLevel=level+1;f.expanded=f.expansionLevel>0;$('#modal-dialog').close();save();render();guideEvent('expand');notify('A new sunny meadow band is open — '+newTiles+' grass tiles added! ✨')}}
